function safeParse(raw, fallback) {
  try {
    const cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) { return fallback; }
}

// Certifications: single output from Recommend Certification
const certRaw = safeParse($('Recommend Certification').first().json.output, { recommendations: [] });

// Roadmaps: one output PER item from Career Roadmap Generator
const roadmapItems = $('Career Roadmap Generator').all();

const career_roadmaps = roadmapItems
  .map(item => safeParse(item.json.output, { career_roadmap: null }).career_roadmap)
  .filter(Boolean);

return [{
  json: {
    certifications: certRaw.recommendations || [],
    career_roadmaps: career_roadmaps,
  }
}];
